// Preload hook: counts sync fs calls in this process.
// Usage: NODE_OPTIONS="--import /abs/path/fs-count.mjs" FS_COUNT_DIR=/abs/dir <command>
// Every 200 ms each thread writes <FS_COUNT_DIR>/<pid>-<threadId>.json = { argv, counts } (written atomically; its own writes are not counted).
import fs from "node:fs";
import { syncBuiltinESMExports } from "node:module";
import path from "node:path";
import { threadId } from "node:worker_threads";

const dir = process.env.FS_COUNT_DIR;
if (dir) {
  const names = ["lstatSync", "statSync", "readdirSync", "realpathSync", "openSync", "readFileSync", "existsSync", "mkdirSync", "rmdirSync", "rmSync"];
  const counts = Object.fromEntries(names.map((n) => [n, 0]));
  let paused = false;
  for (const name of names) {
    const orig = fs[name];
    const wrapped = function (...args) {
      if (!paused) counts[name] += 1;
      return orig.apply(this, args);
    };
    if (orig.native) wrapped.native = orig.native;
    fs[name] = wrapped;
  }
  syncBuiltinESMExports();
  const file = path.join(dir, `${process.pid}-${threadId}.json`);
  const flush = () => {
    paused = true;
    try {
      fs.writeFileSync(`${file}.tmp`, JSON.stringify({ argv: process.argv.slice(1), counts }));
      fs.renameSync(`${file}.tmp`, file);
    } finally {
      paused = false;
    }
  };
  setInterval(flush, 200).unref();
  process.on("exit", flush);
}
```

