```js
// Isolated-Gateway proof for findDuplicateAgentDirs probe work.
// Usage: node e2e-gateway.mjs <built-openclaw-checkout> <label> [N=10]
// Env: RELOAD=off|hybrid (default off), PORT (default 19431).
// Starts `openclaw gateway run` from <checkout>/dist/entry.js with its own temp HOME,
// state dir, config and loopback port (never the live Gateway), preloading fs-count.mjs.
// Then: (1) 32 agents with distinct existing agentDirs: one cold `gateway call config.get`,
// 5 warm (cached) calls, and N edit cycles (rewrite the config, wait 1.5 s, config.get),
// counting sync fs calls in all threads of the Gateway process; (2) with reload.mode=off,
// rewrites the config with a genuine alias pair (missing case variants, existing case
// variants, symlink) and prints config.get validity + issues and `openclaw config validate`.
import { spawn, spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repo = path.resolve(process.argv[2]);
const label = process.argv[3] ?? "run";
const N = Number(process.argv[4] ?? 10);
const reload = process.env.RELOAD ?? "off";
const port = Number(process.env.PORT ?? 19431);
const hook = path.join(path.dirname(fileURLToPath(import.meta.url)), "fs-count.mjs");
const entry = path.join(repo, "dist/entry.js");

const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "oc-f1-e2e-")));
const home = path.join(root, "home");
const state = path.join(home, ".openclaw");
const countDir = path.join(root, "fs-counts");
const configPath = path.join(state, "openclaw.json");
const agentsRoot = path.join(root, "agents");
for (const d of [state, countDir, agentsRoot]) fs.mkdirSync(d, { recursive: true });

const redact = (s) =>
  String(s).replaceAll(root, "<tmp>").replaceAll(os.homedir(), "~").replaceAll(String(port), "<port>");
const log = (...a) => console.log(redact(a.join(" ")));

const ids = Array.from({ length: 32 }, (_, i) => `a${i}`);
for (const id of ids) fs.mkdirSync(path.join(agentsRoot, id, "agent"), { recursive: true });
const distinctEntries = Object.fromEntries(
  ids.map((id) => [id, { name: id, agentDir: path.join(agentsRoot, id, "agent") }]),
);
const writeConfig = (entries) =>
  fs.writeFileSync(
    configPath,
    `${JSON.stringify(
      {
        browser: { enabled: false },
        update: { checkOnStart: false },
        discovery: { mdns: { mode: "off" } },
        gateway: {
          mode: "local",
          bind: "loopback",
          port,
          auth: { mode: "none" },
          controlUi: { enabled: false },
          tailscale: { mode: "off" },
          reload: { mode: reload },
        },
        agents: { ownership: "explicit", entries },
      },
      null,
      2,
    )}\n`,
  );
writeConfig(distinctEntries);

const baseEnv = {
  PATH: process.env.PATH,
  HOME: home,
  TMPDIR: path.join(root, "tmp"),
  OPENCLAW_STATE_DIR: state,
  OPENCLAW_CONFIG_PATH: configPath,
  OPENCLAW_SKIP_CHANNELS: "1",
};
fs.mkdirSync(baseEnv.TMPDIR, { recursive: true });

const cli = (args) =>
  spawnSync(process.execPath, [entry, ...args], { env: baseEnv, encoding: "utf8", timeout: 60_000 });
const callConfigGet = () => {
  const r = cli(["gateway", "call", "config.get", "--port", String(port), "--json", "--timeout", "30000"]);
  if (r.status !== 0) throw new Error(`config.get exit ${r.status}: ${redact(r.stderr).slice(0, 600)}`);
  return JSON.parse(r.stdout.slice(r.stdout.indexOf("{")));
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
// Sums all threads (main + workers) of the spawned Gateway process.
const gatewayCounts = () => {
  const counts = {};
  let threads = 0;
  for (const f of fs.readdirSync(countDir)) {
    if (!f.startsWith(`${gw.pid}-`) || !f.endsWith(".json")) continue;
    threads += 1;
    const data = JSON.parse(fs.readFileSync(path.join(countDir, f), "utf8"));
    for (const [k, v] of Object.entries(data.counts)) counts[k] = (counts[k] ?? 0) + v;
  }
  if (!threads) throw new Error(`no fs-count file for gateway pid; files: ${fs.readdirSync(countDir).length}`);
  return { threads, counts };
};
const diff = (a, b, per = 1) =>
  Object.fromEntries(
    Object.keys(b.counts)
      .map((k) => [k, +((b.counts[k] - (a.counts[k] ?? 0)) / per).toFixed(1)])
      .filter(([, v]) => v !== 0),
  );

const gw = spawn(
  process.execPath,
  [entry, "gateway", "run", "--port", String(port), "--bind", "loopback", "--auth", "none", "--tailscale", "off", "--allow-unconfigured"],
  { env: { ...baseEnv, NODE_OPTIONS: `--import ${hook}`, FS_COUNT_DIR: countDir }, stdio: ["ignore", "pipe", "pipe"] },
);
let gwOut = "";
gw.stdout.on("data", (d) => (gwOut += d));
gw.stderr.on("data", (d) => (gwOut += d));

try {
  log(`== ${label}: node ${process.version}, ${os.platform()} ${os.arch()}, reload.mode=${reload}, ${ids.length} agents, N=${N}`);
  let ready = false;
  for (let i = 0; i < 90 && !ready; i++) {
    if (gw.exitCode !== null) throw new Error(`gateway exited ${gw.exitCode}: ${redact(gwOut).slice(-1500)}`);
    ready = cli(["gateway", "call", "health", "--port", String(port), "--json", "--timeout", "3000"]).status === 0;
    if (!ready) await sleep(1000);
  }
  if (!ready) throw new Error(`gateway not ready: ${redact(gwOut).slice(-1500)}`);
  log("gateway ready (health ok)");
  // Startup work continues after health is ok; wait for a quiet 2 s window.
  const total = (d) => Object.values(d).reduce((a, b) => a + b, 0);
  let quiet;
  for (let i = 0, prev = gatewayCounts(); i < 60; i++) {
    await sleep(2000);
    const cur = gatewayCounts();
    quiet = diff(prev, cur);
    prev = cur;
    if (total(quiet) < 50) break;
  }
  log(`settled: quiet 2 s window, gateway sync fs calls: ${JSON.stringify(quiet)}`);

  // config.get is cached per watcher-owned config revision, so measure a cold
  // miss, warm hits, and N edit cycles (rewrite config, then config.get).
  const sample = async (fn) => {
    const before = gatewayCounts();
    const res = await fn();
    await sleep(400);
    return { res, d: diff(before, gatewayCounts()) };
  };
  const mean = (ds) => {
    const out = {};
    for (const d of ds) for (const [k, v] of Object.entries(d)) out[k] = (out[k] ?? 0) + v / ds.length;
    return Object.fromEntries(Object.entries(out).map(([k, v]) => [k, +v.toFixed(1)]));
  };
  const lstats = (ds) => JSON.stringify(ds.map((d) => d.lstatSync ?? 0));
  const getValid = () => {
    const res = callConfigGet();
    if (res.valid !== true) throw new Error(`distinct config not valid: ${JSON.stringify(res.issues)}`);
    return res;
  };

  const cold = await sample(getValid);
  log(`config.get cold (first after start): valid=${cold.res.valid}, agents.entries=${Object.keys(cold.res.config?.agents?.entries ?? {}).length}, fs ${JSON.stringify(cold.d)}`);
  const warm = [];
  for (let i = 0; i < 5; i++) warm.push((await sample(getValid)).d);
  log(`config.get warm cache hits x5, mean fs: ${JSON.stringify(mean(warm))}`);

  const watch = [];
  const calls = [];
  for (let i = 0; i < N; i++) {
    const w = await sample(async () => {
      writeConfig({ ...distinctEntries, a0: { ...distinctEntries.a0, name: `a0 edit ${i}` } });
      await sleep(1500);
    });
    watch.push(w.d);
    const c = await sample(getValid);
    if (c.res.config?.agents?.entries?.a0?.name !== `a0 edit ${i}`) throw new Error("config.get missed the edit");
    calls.push(c.d);
  }
  log(`edit cycles x${N}: watcher work after each edit, mean fs: ${JSON.stringify(mean(watch))}`);
  log(`edit cycles x${N}: config.get after each edit (cache miss, saw the edit), mean fs: ${JSON.stringify(mean(calls))}`);
  log(`  lstat per config.get, in order: ${lstats(calls)}`);
  const idle = [];
  for (let i = 0; i < 3; i++) idle.push((await sample(() => sleep(1500))).d);
  log(`idle control 1.9 s windows x3, mean fs: ${JSON.stringify(mean(idle))}`);

  if (reload === "off") {
    // Genuine aliases on a case-insensitive volume: missing and existing case variants, and a symlink.
    fs.mkdirSync(path.join(agentsRoot, "Team"), { recursive: true });
    fs.mkdirSync(path.join(agentsRoot, "real"), { recursive: true });
    fs.symlinkSync(path.join(agentsRoot, "real"), path.join(agentsRoot, "link"));
    const cases = {
      "missing case-variant alias (Future vs future, neither exists)": { future: { agentDir: path.join(agentsRoot, "Future") }, future2: { agentDir: path.join(agentsRoot, "future") } },
      "existing case-variant alias (Team exists, team configured)": { upper: { agentDir: path.join(agentsRoot, "Team") }, lower: { agentDir: path.join(agentsRoot, "team") } },
      "symlink alias (real vs link)": { real: { agentDir: path.join(agentsRoot, "real") }, link: { agentDir: path.join(agentsRoot, "link") } },
    };
    for (const [name, extra] of Object.entries(cases)) {
      writeConfig({ ...distinctEntries, ...extra });
      const res = callConfigGet();
      log(`-- ${name}: config.get valid=${res.valid}`);
      // First line of each issue plus its conflict lines; the rest is fixed help text.
      const brief = (m) => [m.split("\n")[0], ...m.split("\n").filter((l) => l.startsWith("- "))].join(" | ");
      for (const issue of res.issues ?? []) log(`   issue ${issue.path}: ${brief(issue.message)}`);
      const v = cli(["config", "validate"]);
      const out = `${v.stdout}${v.stderr}`.replaceAll("\\n", "\n");
      log(`   openclaw config validate: exit ${v.status}; ${brief(out.slice(out.indexOf("Duplicate agentDir")))}`);
    }
    writeConfig(distinctEntries);
  }
} finally {
  gw.kill("SIGTERM");
  for (let i = 0; i < 40 && gw.exitCode === null; i++) await sleep(250);
  if (gw.exitCode === null) gw.kill("SIGKILL");
  fs.rmSync(root, { recursive: true, force: true });
}
